```js
function sortConcurrencyEvents(events) {
   events.sort(function(a, b) {
       if (a.time !== b.time) return a.time - b.time;
       return a.delta - b.delta;
   });
}

function concurrencyEventsOf(intervals) {
   var events = [];
   intervals.forEach(function(interval) {
       events.push({ time: interval.start, delta: 1 });
       events.push({ time: interval.end, delta: -1 });
   });
   sortConcurrencyEvents(events);
   return events;
}

function maxConcurrentOf(events) {
   var concurrent = 0;
   var maxConcurrent = 0;
   events.forEach(function(event) {
       concurrent += event.delta;
       if (concurrent > maxConcurrent) maxConcurrent = concurrent;
   });
   return maxConcurrent;
}
```
