// Up to `atempts` GET-sha → merge → PUT cycles; a conflicting PUT refetches
// and retries (sh backoff: sleep attempt*2s between attempts, never after
// the last). Returns the terminal publish outcome.
function putRowWithRetries(io, repo, path, branch, now, attempts, key, leg, row, cutoff, log, sleepMs) {
   for (var attempt = 1; attempt <= attempts; attempt++) {
       if (putTokenRowAttempt(io, repo, path, branch, now, attempt, key, leg, row, cutoff)) {
